SELECT "nct", "author", "year", "pubmed_id", "trial_phase", "treatment_regimen", "name_of_ici", "class_of_ici", "type_of_combination", "control_regimen" FROM public."clinical_trials" WHERE "trial_phase" = '3' AND "class_of_ici" = 'PD1' AND "name_of_ici" ILIKE '%PDL1%' AND "name_of_ici" ILIKE '%CTLA4%' AND "cancer_type" = 'Non-Small Cell Lung Cancer' AND "type_of_combination" = 'Combination Therapy';